from pathlib import Path

def write(path: str, content: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')

write('supabase/functions/ml-service/index.ts', 'import { createClient } from "https://esm.sh/@supabase/supabase-js@2";\nimport { serve } from "https://deno.land/std@0.224.0/http/server.ts";\n\nconst corsHeaders = {\n  "Access-Control-Allow-Origin": "*",\n  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",\n  "Access-Control-Allow-Methods": "POST, OPTIONS",\n};\n\nconst routeMap: Record<string, { path: string; method: string; admin: boolean }> = {\n  modelHealth: { path: "/v1/model-health", method: "GET", admin: false },\n  modelVersions: { path: "/v1/model-versions", method: "GET", admin: false },\n  predictMarket: { path: "/v1/predict-market", method: "POST", admin: false },\n  explainPrediction: { path: "/v1/explain-prediction", method: "POST", admin: false },\n  listStations: { path: "/v1/stations", method: "GET", admin: false },\n  listDatasets: { path: "/v1/datasets", method: "GET", admin: false },\n  createBacktest: { path: "/v1/backtest-strategy", method: "POST", admin: false },\n  getBacktest: { path: "/v1/backtest-runs/{id}", method: "GET", admin: false },\n  getTrainingJob: { path: "/v1/training-jobs/{id}", method: "GET", admin: true },\n  trainCandidate: { path: "/v1/train-candidate", method: "POST", admin: true },\n  evaluateCandidate: { path: "/v1/evaluate-candidate", method: "POST", admin: true },\n  promoteModel: { path: "/v1/promote-model", method: "POST", admin: true },\n  rollbackModel: { path: "/v1/rollback-model", method: "POST", admin: true },\n  recordOutcome: { path: "/v1/record-outcome", method: "POST", admin: true },\n};\n\ntype ProxyRequest = {\n  action: keyof typeof routeMap;\n  id?: string;\n  payload?: unknown;\n};\n\nfunction jsonResponse(body: unknown, status = 200): Response {\n  return new Response(JSON.stringify(body), {\n    status,\n    headers: { ...corsHeaders, "Content-Type": "application/json" },\n  });\n}\n\nserve(async (request: Request) => {\n  if (request.method === "OPTIONS") {\n    return new Response("ok", { headers: corsHeaders });\n  }\n  if (request.method !== "POST") {\n    return jsonResponse({ error: "Method not allowed" }, 405);\n  }\n\n  const mlServiceUrl = Deno.env.get("ML_SERVICE_URL")?.replace(/\\\/$/, "");\n  const mlServiceApiKey = Deno.env.get("ML_SERVICE_API_KEY");\n  const mlServiceAdminKey = Deno.env.get("ML_SERVICE_ADMIN_API_KEY");\n  const supabaseUrl = Deno.env.get("SUPABASE_URL");\n  const supabaseAnonKey = Deno.env.get("SUPABASE_ANON_KEY");\n\n  if (!mlServiceUrl || !mlServiceApiKey || !supabaseUrl || !supabaseAnonKey) {\n    return jsonResponse({ error: "ML service or Supabase secrets are not configured" }, 500);\n  }\n\n  const authorization = request.headers.get("Authorization");\n  if (!authorization) {\n    return jsonResponse({ error: "Authentication required" }, 401);\n  }\n\n  const supabase = createClient(supabaseUrl, supabaseAnonKey, {\n    global: { headers: { Authorization: authorization } },\n    auth: { persistSession: false },\n  });\n  const { data: userResult, error: userError } = await supabase.auth.getUser();\n  if (userError || !userResult.user) {\n    return jsonResponse({ error: "Invalid user session" }, 401);\n  }\n\n  let input: ProxyRequest;\n  try {\n    input = await request.json();\n  } catch {\n    return jsonResponse({ error: "Invalid JSON body" }, 400);\n  }\n\n  const route = routeMap[input.action];\n  if (!route) {\n    return jsonResponse({ error: "Unsupported ML service action" }, 400);\n  }\n\n  if (route.admin) {\n    if (!mlServiceAdminKey) {\n      return jsonResponse({ error: "ML admin secret is not configured" }, 500);\n    }\n    const { data: profile, error: profileError } = await supabase\n      .from("users_profiles")\n      .select("role")\n      .eq("user_id", userResult.user.id)\n      .single();\n    if (profileError || !profile || !["Owner", "Administrator"].includes(profile.role)) {\n      return jsonResponse({ error: "Administrator access required" }, 403);\n    }\n  }\n\n  let path = route.path;\n  if (path.includes("{id}")) {\n    if (!input.id || !/^[a-zA-Z0-9_-]+$/.test(input.id)) {\n      return jsonResponse({ error: "A valid resource id is required" }, 400);\n    }\n    path = path.replace("{id}", encodeURIComponent(input.id));\n  }\n\n  const headers: Record<string, string> = {\n    Accept: "application/json",\n    "X-API-Key": mlServiceApiKey,\n    "X-Request-ID": crypto.randomUUID(),\n  };\n  if (route.admin) {\n    headers["X-Admin-Key"] = mlServiceAdminKey!;\n  }\n  if (route.method !== "GET") {\n    headers["Content-Type"] = "application/json";\n  }\n\n  const upstream = await fetch(`${mlServiceUrl}${path}`, {\n    method: route.method,\n    headers,\n    body: route.method === "GET" ? undefined : JSON.stringify(input.payload ?? {}),\n  });\n\n  const responseText = await upstream.text();\n  let responseBody: unknown;\n  try {\n    responseBody = responseText ? JSON.parse(responseText) : null;\n  } catch {\n    responseBody = { raw: responseText };\n  }\n\n  return jsonResponse(responseBody, upstream.status);\n});\n')
